		}
	}
	return res
}

func stateFilePath(t *testing.T) string {
	t.Helper()
	return filepath.Join(t.TempDir(), "state.json")
}

func readStateFileRaw(t *testing.T, path string) (revision int64, resources []stateResource) {
	t.Helper()
	data, err := os.ReadFile(path)
